mapper.insert:
   INSERT INTO custom_delivery_record(id,custom_order_id,delivery_version,delivery_request_id,delivery_mode,delivery_status,pickup_registered_at,delivered_at,acceptance_deadline_at,
delivery_address_snapshot,evidence_json,order_item_ids_json,remark,operator_user_id,version,created_at,updated_at)
SELECT #{id},o.id,COALESCE(old.delivery_version,0)+1,#{key},o.delivery_mode,IF(#{pickup},'awaiting_pickup_confirmation','delivered'),IF(#{pickup},#{occurred},NULL),
IF(#{pickup},NULL,#{occurred}),IF(#{pickup},NULL,DATE_ADD(CAST(#{occurred} AS DATETIME(3)),INTERVAL 48 HOUR)),o.delivery_address_snapshot,#{evidence},#{items},#{remark},#{actor},0,#{at},#{at}
FROM custom_order o LEFT JOIN custom_delivery_record old ON old.id=o.current_delivery_record_id WHERE o.id=#{order}

mapper.update:
   UPDATE custom_order o JOIN custom_delivery_record d ON d.custom_order_id=o.id AND d.id=#{delivery}
SET o.current_delivery_record_id=d.id,o.delivered_at=d.delivered_at,o.acceptance_deadline_at=d.acceptance_deadline_at,o.acceptance_paused_at=NULL,o.acceptance_remaining_seconds=NULL,
o.acceptance_status=IF(d.delivered_at IS NULL,'not_started','running'),o.order_status=IF(d.delivered_at IS NULL,'delivering','pending_acceptance'),o.updated_at=#{at},o.version=o.version+1 WHERE o.id=#{order}

   UPDATE custom_order o JOIN custom_delivery_record d ON d.id=o.current_delivery_record_id AND d.id=#{delivery}
SET o.order_status='completed',o.acceptance_status='accepted',o.accepted_at=#{at},o.completed_at=#{at},o.version=o.version+1,o.updated_at=#{at},d.delivery_status='accepted',d.updated_at=#{at},d.version=d.version+1
WHERE o.id=#{id} AND o.order_status='pending_acceptance' AND o.acceptance_status='running' AND d.delivery_status='delivered' AND NOT EXISTS(SELECT 1 FROM custom_after_sale_request a WHERE a.active_order_guard=o.id)

mapper.insert:
   INSERT INTO custom_order_extension_request(id,extension_request_no,submit_idempotency_key,custom_order_id,factory_id,original_promised_date,requested_promised_date,request_reason,evidence_json,request_status,version,created_at,updated_at)
SELECT #{id},CONCAT('CE',#{id}),#{key},o.id,o.factory_id,o.promised_completion_date,#{input.requestedDate},#{input.reason},#{evidence},'draft',0,#{at},#{at} FROM custom_order o WHERE o.id=#{order}
ON DUPLICATE KEY UPDATE requested_promised_date=#{input.requestedDate},request_reason=#{input.reason},evidence_json=#{evidence},version=custom_order_extension_request.version+1,updated_at=#{at}
